<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;
class FeedbackResponse extends Model{use HasFactory;protected $fillable=['public_id','campus_id','building_id','floor_id','survey_area_id','ssid','problem_type','connection_stability','speed_satisfaction','overall_satisfaction','activity_type','buffering','disconnection_count','comment','consent','status','experienced_at','submitted_at','source_ip_hash','user_agent_hash'];protected function casts():array{return ['buffering'=>'boolean','consent'=>'boolean','experienced_at'=>'datetime','submitted_at'=>'datetime'];}public function campus(){return $this->belongsTo(Campus::class);}public function building(){return $this->belongsTo(Building::class);}public function floor(){return $this->belongsTo(Floor::class);}public function surveyArea(){return $this->belongsTo(SurveyArea::class);}public function correlations(){return $this->hasMany(FeedbackCorrelation::class);}}
